/**
 * Parity tests for the diff engine.
 *
 * `fixtures/diff-golden.json` was generated by the original Go implementation
 * (eleview's internal/diff) over a corpus of real `git diff -U99999` output,
 * including files with no trailing newline on either side. Every assertion here
 * is "the TS port produces exactly what Go produced" — byte for byte for the
 * patch strings, because those go straight into `git apply --cached`.
 *
 * The include-set strategies below MUST stay identical to the ones in the
 * generator, or the comparison is meaningless.
 */
import { describe, expect, test } from 'bun:test'
import {
  align,
  buildPartialPatch,
  computeStagedIndices,
  filterContentLines,
  LineKind,
  parse,
  type Line,
} from '../src/diff.ts'
import golden from './fixtures/diff-golden.json' with { type: 'json' }

interface GoldenLine {
  text: string
  kind: number
  oldNum: number
  newNum: number
  noNewline: boolean
}
interface GoldenRow {
  kind: number
  oldNum: number
  newNum: number
  oldText: string
  newText: string
  oldSrcIdx: number
  newSrcIdx: number
}
interface GoldenCase {
  name: string
  diff: string
  lines: GoldenLine[]
  aligned: GoldenRow[]
  patches: Record<string, string>
  stagedRoundTrip: Record<string, number[]>
}

const cases = (golden as { cases: GoldenCase[] }).cases
const PATCH_PATH = 'f.txt'

/** Mirrors strategies() in cmd/genfixtures/main.go. */
function strategies(lines: Line[]): Record<string, Set<number>> {
  const changed: number[] = []
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].kind === LineKind.Add || lines[i].kind === LineKind.Del) changed.push(i)
  }
  const set = (pred: (pos: number, idx: number) => boolean) => {
    const s = new Set<number>()
    changed.forEach((idx, pos) => {
      if (pred(pos, idx)) s.add(idx)
    })
    return s
  }
  return {
    all: set(() => true),
    evens: set((pos) => pos % 2 === 0),
    odds: set((pos) => pos % 2 === 1),
    third: set((pos) => pos % 3 === 0),
    adds: set((_, idx) => lines[idx].kind === LineKind.Add),
    dels: set((_, idx) => lines[idx].kind === LineKind.Del),
    first: changed.length > 0 ? new Set([changed[0]]) : new Set<number>(),
    last: changed.length > 0 ? new Set([changed[changed.length - 1]]) : new Set<number>(),
  }
}

test('fixture corpus is non-trivial', () => {
  expect(cases.length).toBe(14)
  expect(cases.some((c) => c.name.includes('nonl'))).toBe(true)
})

describe.each(cases.map((c) => [c.name, c] as const))('%s', (_name, c) => {
  const combined = filterContentLines(parse(c.diff))

  test('parse matches Go', () => {
    expect(combined.length).toBe(c.lines.length)
    expect(
      combined.map((l) => ({
        text: l.text,
        kind: l.kind as number,
        oldNum: l.oldNum,
        newNum: l.newNum,
        noNewline: l.noNewline,
      })),
    ).toEqual(c.lines)
  })

  test('align matches Go', () => {
    const rows = align(combined)
    expect(rows.length).toBe(c.aligned.length)
    expect(
      rows.map((r) => ({
        kind: r.kind as number,
        oldNum: r.oldNum,
        newNum: r.newNum,
        oldText: r.oldText,
        newText: r.newText,
        oldSrcIdx: r.oldSrcIdx,
        newSrcIdx: r.newSrcIdx,
      })),
    ).toEqual(c.aligned)
  })

  const strats = strategies(combined)

  test('buildPartialPatch is byte-identical to Go for every include set', () => {
    for (const [name, include] of Object.entries(strats)) {
      const got = buildPartialPatch(PATCH_PATH, combined, include)
      // Compare explicitly per strategy so a failure names the culprit.
      expect(got, `strategy=${name}`).toBe(c.patches[name]!)
    }
  })

  test('computeStagedIndices round-trips the include set', () => {
    for (const [name, include] of Object.entries(strats)) {
      const patch = buildPartialPatch(PATCH_PATH, combined, include)
      let recovered: number[] = []
      if (patch !== '') {
        const stagedLines = filterContentLines(parse(patch))
        recovered = [...computeStagedIndices(combined, stagedLines)].sort((a, b) => a - b)
      }
      expect(recovered, `strategy=${name}`).toEqual(c.stagedRoundTrip[name]!)
    }
  })
})
